using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Analytic.GaussZeroBalanced;

internal sealed class ParamDerivDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Parameter derivatives of the zero-balanced quotient", H("Differentiation and the parameter threshold"), Blocks(
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-hasderivat-f-param-of-gauss"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.hasDerivAt_f_param_of_gauss"),
                H("The parameter quotient rule"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Given the parameter derivatives of G and H and a nonzero H, the parameter derivative of f=G/H is (G_b H-G H_b)/H squared."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-parameter-riccati-deriv"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.parameter_riccati_deriv"),
                H("Differentiating the Riccati identity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b, differentiating the Riccati identity in a neighborhood of b gives x K_b+(a+b+2ab x F/((a+b)(1-x)))F_b=(1-F)-a squared x F squared/((a+b) squared (1-x)). The hypotheses give the two parameter derivatives and the local Riccati identity."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-hasderivat-gauss-param"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.hasDerivAt_gauss_param"),
                H("Parameter differentiation of Gauss series"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b, a+s>0 and abs(x)<1, the derivative in b of gauss a b (a+b+s) x equals the sum of the parameter derivatives of its coefficients times x to the coefficient index. The coefficient is the binomial coefficient (a)_n/n! times a product of n factors (b+j)/(a+b+s+j). Each factor lies between zero and one, and its derivative lies between zero and 1/b. On a fixed parameter interval bounded away from zero, n(a)_n/(n! b) is therefore a uniform coefficient derivative bound. The unit convergence radius and polynomially weighted geometric summability justify differentiating the sum."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-hasderivat-f-param"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.hasDerivAt_f_param"),
                H("Parameter differentiability of the contiguous quotient"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b and 0<=x<1, the function beta maps to f a beta x is differentiable at b. The two parameter derivative series and the positive denominator discharge the quotient rule."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-gaussparam"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.gaussParam"),
                H("The parameter derivative series"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The function gaussParam a b s x is the sum over n of the derivative at b of the nth coefficient of gauss a beta (a+beta+s), multiplied by x to the nth power."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-hasderivat-gaussparam"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.hasDerivAt_gaussParam"),
                H("Argument differentiation of the parameter series"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b, a+s>0 and abs(x)<1, the argument derivative of gaussParam is the sum of n times its nth parameter derivative coefficient times x to the power n-1. A polynomially weighted coefficient bound supplies a summable majorant on every smaller argument interval."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-hasderivat-gauss-mixed"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.hasDerivAt_gauss_mixed"),
                H("The mixed Gauss derivative"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b, a+s>0 and abs(x)<1, the parameter derivative of the argument derivative of gauss equals the argument derivative of gaussParam. Both orders of differentiation give the same convergent series with nth term n times the parameter derivative of the nth coefficient times x to the power n-1."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-hasderivat-f-mixed"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.hasDerivAt_f_mixed"),
                H("The mixed quotient derivative"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b and 0<=x<1, both mixed derivatives of f exist and are equal. The numerator and denominator mixed Gauss derivatives pass through the quotient rule. Nonvanishing of the denominator extends to a neighborhood of the argument, including a two-sided neighborhood at zero."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-deriv-f-param-zero"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.deriv_f_param_zero"),
                H("The parameter derivative at zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every real a and b, the parameter derivative of f at x=0 is zero because f a beta 0 is the constant one."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-hasderivat-f-param-zero"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.hasDerivAt_f_param_zero"),
                H("The initial mixed derivative"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b, the argument derivative at zero of the parameter derivative of f is a times (b squared-a(a+1)) divided by the product of (a+b) squared and (a+b+1) squared. This follows from the proved mixed derivative identity and parameter differentiation of the initial slope -ab/((a+b)(a+b+1))."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-parameter-equation"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.parameter_equation"),
                H("The parameter variational equation"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b and 0<x<1, write h(x) for the parameter derivative of f at b, c=a+b and t=x/(1-x). Then x h prime+(c+2ab t f/c)h=(1-f)-a squared t f squared/c squared. The mixed derivative identity justifies differentiating the Riccati equation."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-hasderivat-quot-param"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.hasDerivAt_quot_param"),
                H("Parameter differentiation of the original quotient"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive a and b and 0<=x<1, the parameter derivative of quot equals the parameter derivative of f divided by 1-x. The contiguous identity relates the two functions throughout a parameter neighborhood."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gauss-zero-balanced-param-clause1"),
                DeclarationHandle.Create("D5/S3/Analytic/GaussZeroBalanced/ParamDeriv.clause1"),
                H("The first parameter classification"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive real a and b, the parameter derivative of quot is strictly negative at every x in (0,1) if and only if b<=sqrt(a(a+1)). For sufficiency, the certificate bounds (1-f)/(t f squared) strictly below ab/(c(c+1)), and the threshold puts this upper bound at most a squared/c squared. The singular endpoint comparison applied to minus h proves strict negativity. For necessity, strict negativity on (0,1) makes zero a right-side maximum of h; its initial derivative must be nonpositive, forcing b squared<=a(a+1)."))), DescribeRole.Theorem))));
}
